044f \u0446\u044c\u043e\u0433\u043e \u043f\u0456\u0434\u0439\u043e\u043c\u0443. \u0417\u0432\u043e\u0440\u043e\u0442\u043d\u0438\u0439 \u0448\u043b\u044f\u0445, \u043f\u0435\u0440\u0435\u0445\u0456\u0434 \u043d\u0430 Dzikowiec \u0456 \u043f\u0456\u0434\u0445\u0456\u0434 \u0434\u043e \u0432\u0456\u0442\u0440\u043e\u0432\u0438\u0445 \u0449\u0456\u043b\u0438\u043d \u043d\u0435 \u0432\u0445\u043e\u0434\u044f\u0442\u044c \u0434\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443. \u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0442\u043e\u0447\u043d\u0456 \u0443\u043c\u043e\u0432\u0438."},"zh":{"name":"Lesista Wielka\uff1a\u4eceMierosz\u00f3w\u6cbf\u9ec4\u8272\u6b65\u9053\u4e0a\u884c","description":"\u4eceMierosz\u00f3w\u7684\u8d77\u70b9\uff0850.666706\uff0c16.186379\uff09\u5355\u7a0b\u4e0a\u884c\u3002\u5148\u6cbf\u9053\u8def\u5230\u8fbe\u516c\u5893\u9644\u8fd1\u7684\u9ec4\u8272\u6b65\u9053\uff0c\u518d\u6309\u9ec4\u8272\u6807\u8bb0\u524d\u5f80Lesista Wielka 1\u6b65\u9053\u70b9\u3002","notes":"\u672c\u6bb5\u8def\u7ebf\u957f4.8\u516c\u91cc\u3001\u7d2f\u8ba1\u722c\u5347350\u7c73\uff0c\u9884\u8ba1\u7528\u65f61\u5c0f\u65f648\u5206\u949f\u3002\u4e0d\u5305\u542b\u8fd4\u7a0b\u3001\u524d\u5f80Dzikowiec\u7684\u8def\u6bb5\u6216\u524d\u5f80\u98ce\u7a74\u7684\u652f\u8def\u3002\u51fa\u53d1\u524d\u8bf7\u6838\u5b9e\u5f53\u524d\u72b6\u51b5\u3002"}},"distance_source_url":"https://mapa-turystyczna.pl/route/kmo2","distance_verified_at":"2026-11-28T00:00:00Z","elevation_gain_source_url":"https://mapa-turystyczna.pl/route/kmo2","elevation_gain_verified_at":"2026-11-28T00:00:00Z","time_source_url":"https://mapa-turystyczna.pl/route/kmo2","time_verified_at":"2026-11-28T00:00:00Z"}},{"kind":"poi","body":{"peak_slug":"suchawa","trail_id":null,"type_slug":"shelter","latitude":50.684767,"longitude":16.277919,"active":true,"source_url":"https://dolnoslaskie.szlaki.pttk.pl/1120-dolnoslaskie-schronisko-andrzejowka","last_verified_at":"2026-11-28T00:00:00Z","website_url":null,"google_maps_url":null,"i18n":{"pl":{"name":"Schronisko PTTK Andrzej\u00f3wka","description":"Schronisko i w\u0119ze\u0142 szlak\u00f3w na Prze\u0142\u0119czy Trzech Dolin, pomi\u0119dzy Walig\u00f3r\u0105, Klinem i Graniczn\u0105. Punkt wypadowy do zaplanowania podej\u015bcia w kierunku Suchawy.","tips":"Godziny otwarcia i dost\u0119pno\u015b\u0107 us\u0142ug sprawd\u017a bezpo\u015brednio u gospodarza. Ta karta nie potwierdza wolnych nocleg\u00f3w ani miejsc parkingowych."},"en":{"name":"PTTK Andrzej\u00f3wka hut","description":"Mountain hut and trail junction at Prze\u0142\u0119cz Trzech Dolin, between Walig\u00f3ra, Klin and Graniczna. A base for planning an ascent towards Suchawa.","tips":"Check opening hours and available services directly with the operator. This card does not confirm accommodation or parking availability."},"ua":{"name":"\u041f\u0440\u0438\u0442\u0443\u043b\u043e\u043a PTTK Andrzej\u00f3wka","description":"\u0413\u0456\u0440\u0441\u044c\u043a\u0438\u0439 \u043f\u0440\u0438\u0442\u0443\u043b\u043e\u043a \u0456 \u0432\u0443\u0437\u043e\u043b \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0456\u0432 \u043d\u0430 Prze\u0142\u0119cz Trzech Dolin, \u043c\u0456\u0436 Walig\u00f3ra, Klin \u0456 Graniczna. \u0412\u0456\u0434\u043f\u0440\u0430\u0432\u043d\u0430 \u0442\u043e\u0447\u043a\u0430 \u0434\u043b\u044f \u043f\u043b\u0430\u043d\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u0456\u0434\u0439\u043e\u043c\u0443 \u0432 \u043d\u0430\u043f\u0440\u044f\u043c\u043a\u0443 Suchawa.","tips":"\u0413\u043e\u0434\u0438\u043d\u0438 \u0440\u043e\u0431\u043e\u0442\u0438 \u0442\u0430 \u043d\u0430\u044f\u0432\u043d\u0456 \u043f\u043e\u0441\u043b\u0443\u0433\u0438 \u0443\u0442\u043e\u0447\u043d\u044e\u0439\u0442\u0435 \u0431\u0435\u0437\u043f\u043e\u0441\u0435\u0440\u0435\u0434\u043d\u044c\u043e \u0432 \u0430\u0434\u043c\u0456\u043d\u0456\u0441\u0442\u0440\u0430\u0446\u0456\u0457. \u0426\u044f \u043a\u0430\u0440\u0442\u043a\u0430 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0432\u0456\u043b\u044c\u043d\u0438\u0445 \u043c\u0456\u0441\u0446\u044c \u0434\u043b\u044f \u043d\u043e\u0447\u0456\u0432\u043b\u0456 \u0447\u0438 \u043f\u0430\u0440\u043a\u0443\u0432\u0430\u043d\u043d\u044f."},"zh":{"name":"PTTK Andrzej\u00f3wka\u5c71\u5c4b","description":"\u4f4d\u4e8ePrze\u0142\u0119cz Trzech Dolin\u7684\u5c71\u5c4b\u4e0e\u6b65\u9053\u4ea4\u6c47\u5904\uff0c\u5730\u5904Walig\u00f3ra\u3001Klin\u548cGraniczna\u4e4b\u95f4\uff0c\u53ef\u4f5c\u4e3a\u89c4\u5212\u524d\u5f80Suchawa\u5f92\u6b65\u8def\u7ebf\u7684\u51fa\u53d1\u70b9\u3002","tips":"\u8bf7\u76f4\u63a5\u5411\u7ecf\u8425\u8005\u6838\u5b9e\u5f00\u653e\u65f6\u95f4\u53ca\u670d\u52a1\u3002\u672c\u5361\u7247\u4e0d\u4fdd\u8bc1\u6709\u4f4f\u5bbf\u7a7a\u4f4d\u6216\u505c\u8f66\u4f4d\u3002"}}}},{"kind":"poi","body":{"peak_slug":"lesista-wielka","trail_id":null,"type_slug":"attraction","latitude":50.7024,"longitude":16.2037,"active":true,"source_url":"https://geosudety.pl/objects/show/187","last_verified_at":"2026-11-28T00:00:00Z","website_url":null,"google_maps_url":null,"i18n":{"pl":{"name":"Ma\u0142a szczelina wiatrowa pod Lesist\u0105 Wielk\u0105","description":"Szczelina wiatrowa na zboczu masywu Lesistej Wielkiej \u2014 osobliwo\u015b\u0107 skalna zwi\u0105zana z wymian\u0105 powietrza w systemie sp\u0119ka\u0144. Znacznik pochodzi ze spo\u0142eczno\u015bciowego katalogu GeoSudety.","tips":"To osobny punkt poza opisanym \u017c\u00f3\u0142tym podej\u015bciem; doj\u015bcie do niego nie jest cz\u0119\u015bci\u0105 GPX. Nie wchod\u017a do szczeliny i zachowaj odst\u0119p od jej kraw\u0119dzi."},"en":{"name":"Small wind fissure below Lesista Wielka","description":"A wind fissure on the slope of the Lesista Wielka massif, a rock feature associated with air circulation through a network of cracks. Its marker comes from the community GeoSudety catalogue.","tips":"This is a separate point outside the described yellow-trail ascent; access to it is not included in the GPX. Do not enter the fissure and keep away from its edges."},"ua":{"name":"\u041c\u0430\u043b\u0430 \u0432\u0456\u0442\u0440\u043e\u0432\u0430 \u0449\u0456\u043b\u0438\u043d\u0430 \u043f\u0456\u0434 Lesista Wielka","description":"\u0412\u0456\u0442\u0440\u043e\u0432\u0430 \u0449\u0456\u043b\u0438\u043d\u0430 \u043d\u0430 \u0441\u0445\u0438\u043b\u0456 \u043c\u0430\u0441\u0438\u0432\u0443 Lesista Wielka \u2014 \u0441\u043a\u0435\u043b\u044c\u043d\u0430 \u043e\u0441\u043e\u0431\u043b\u0438\u0432\u0456\u0441\u0442\u044c, \u043f\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u0430 \u0437 \u0446\u0438\u0440\u043a\u0443\u043b\u044f\u0446\u0456\u0454\u044e \u043f\u043e\u0432\u0456\u0442\u0440\u044f \u0432 \u0441\u0438\u0441\u0442\u0435\u043c\u0456 \u0442\u0440\u0456\u0449\u0438\u043d. \u041f\u043e\u0437\u043d\u0430\u0447\u043a\u0430 \u043f\u043e\u0445\u043e\u0434\u0438\u0442\u044c \u0437\u0456 \u0441\u043f\u0456\u043b\u044c\u043d\u043e\u0442\u043d\u043e\u0433\u043e \u043a\u0430\u0442\u0430\u043b\u043e\u0433\u0443 GeoSudety.","tips":"\u0426\u0435 \u043e\u043a\u0440\u0435\u043c\u0430 \u0442\u043e\u0447\u043a\u0430 \u043f\u043e\u0437\u0430 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u043c \u0436\u043e\u0432\u0442\u0438\u043c \u043f\u0456\u0434\u0439\u043e\u043c\u043e\u043c; \u043f\u0456\u0434\u0445\u0456\u0434 \u0434\u043e \u043d\u0435\u0457 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442\u044c \u0434\u043e GPX. \u041d\u0435 \u0437\u0430\u0445\u043e\u0434\u044c\u0442\u0435 \u0432 \u0449\u0456\u043b\u0438\u043d\u0443 \u0442\u0430 \u0442\u0440\u0438\u043c\u0430\u0439\u0442\u0435\u0441\u044f \u043f\u043e\u0434\u0430\u043b\u0456 \u0432\u0456\u0434 \u0457\u0457 \u043a\u0440\u0430\u0457\u0432."},"zh":{"name":"Lesista Wielka\u4e0b\u65b9\u7684\u5c0f\u98ce\u7a74","description":"\u4f4d\u4e8eLesista Wielka\u5c71\u4f53\u5761\u9762\u7684\u4e00\u5904\u98ce\u7a74\uff0c\u662f\u4e0e\u5ca9\u77f3\u88c2\u9699\u4e2d\u7a7a\u6c14\u6d41\u901a\u6709\u5173\u7684\u5730\u8d28\u666f\u89c2\u3002\u4f4d\u7f6e\u6807\u8bb0\u6765\u81eaGeoSudety\u793e\u533a\u76ee\u5f55\u3002","tips":"\u6b64\u666f\u70b9\u4f4d\u4e8e\u6240\u8ff0\u9ec4\u8272\u4e0a\u5c71\u8def\u7ebf\u4e4b\u5916\uff0cGPX\u4e0d\u5305\u542b\u524d\u5f80\u8be5\u70b9\u7684\u652f\u8def\u3002\u8bf7\u52ff\u8fdb\u5165\u88c2\u9699\uff0c\u5e76\u4e0e\u8fb9\u7f18\u4fdd\u6301\u8ddd\u79bb\u3002"}}}}],"ranges":[{"id":10,"slug":"gory-kamienne"}]}$manifest$::jsonb m),
expected as (select p, (select r->'body' from jsonb_array_elements(m->'records') r where r->>'kind'='trail' and r->'body'->>'peak_slug'=p->>'slug') tb,
 (select r->'body' from jsonb_array_elements(m->'records') r where r->>'kind'='poi' and r->'body'->>'peak_slug'=p->>'slug') pb
 from manifest,jsonb_array_elements(m->'peaks') p)
select e.p->>'slug' peak_slug, mr.slug range_slug,
 (select count(*) from public.trails where peak_id=p.id and active) trails,
 (select count(*) from public.pois where peak_id=p.id and active) pois,
 case when t.route_geometry is not null then 1 else 0 end mapped_trails,
 (select array_agg(lang order by lang collate "C") from public.trails_i18n where trail_id=t.id) trail_languages,
 (select array_agg(lang order by lang collate "C") from public.pois_i18n where poi_id=poi.id) poi_languages,
 coalesce((select jsonb_object_agg(k,to_jsonb(p)->k) from jsonb_object_keys(e.p) k)=e.p
 and mr.slug=(select r->>'slug' from manifest,jsonb_array_elements(m->'ranges') r where (r->>'id')::bigint=p.range_id)
 and not exists(select from unnest(array['peak_id','slug','start_point_name','end_point_name','distance_km','elevation_gain_m','time_min','difficulty','route_type','active','source_url','last_verified_at','map_url','gpx_url','distance_source_url','distance_verified_at','elevation_gain_source_url','elevation_gain_verified_at','time_source_url','time_verified_at','route_geometry','geometry_source_url','geometry_verified_at']) k where to_jsonb(t)->k is distinct from to_jsonb(jsonb_populate_record(null::public.trails,e.tb||jsonb_build_object('peak_id',p.id)))->k)
 and not exists(select from unnest(array['peak_id','trail_id','type_id','latitude','longitude','active','source_url','last_verified_at','website_url','google_maps_url']) k where to_jsonb(poi)->k is distinct from to_jsonb(jsonb_populate_record(null::public.pois,e.pb||jsonb_build_object('peak_id',p.id,'type_id',ty.id)))->k)
 and (select jsonb_object_agg(lang,jsonb_build_object('name',name,'description',description,'notes',notes)) from public.trails_i18n where trail_id=t.id)=e.tb->'i18n'
 and (select jsonb_object_agg(lang,jsonb_build_object('name',name,'description',description,'tips',tips)) from public.pois_i18n where poi_id=poi.id)=e.pb->'i18n',false) review_matches,
 exists(select from peakguide_private.catalogue_batch_receipts where batch_key='nonkgp-07' and snapshot->>'manifest_sha256'='9de8630d6658d6d1d74f26cac59c4a3e9f8480a9b6782cd44dbc7d3da7aa2afb' and snapshot->>'version'='1') package_applied
from expected e left join public.peaks p on p.id=(e.p->>'id')::bigint and p.slug=e.p->>'slug'
left join public.mountain_ranges mr on mr.id=p.range_id
left join public.trails t on t.peak_id=p.id and t.slug=e.tb->>'slug'
left join public.poi_types ty on ty.slug=e.pb->>'type_slug'
left join public.pois poi on poi.peak_id=p.id and poi.source_url=e.pb->>'source_url' and poi.type_id=ty.id
order by e.p->>'slug';
